from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_tilde():
    highlighter = ReprHighlighter()
    text = " https://example.org/~user "
    spans = highlighter.highlight(text)
    print(f"Text: {text}")
    print(f"Spans: {spans}")

    # Expected: a span for 'repr.url' covering 'https://example.org/~user'
    found_url = any(span.style == "repr.url" for span in spans)
    print(f"Found URL span: {found_url}")

    if found_url:
        for span in spans:
            if span.style == "repr.url":
                print(f"URL span: {span.start}:{span.end} -> {text[span.start:span.end]}")
                assert text[span.start:span.end] == "https://example.org/~user"
    else:
        print("No URL span found!")

if __name__ == "__main__":
    test_url_tilde()

